package dns
import("context";"crypto/sha256";"encoding/hex";"fmt";"sort";"strings")
type Record struct{ID string `json:"id"`;Zone string `json:"zone"`;Name string `json:"name"`;Type string `json:"type"`;Value string `json:"value"`;TTL uint32 `json:"ttl"`;Priority uint16 `json:"priority,omitempty"`}
type ZoneSnapshot struct{Provider ProviderType `json:"provider"`;Zone string `json:"zone"`;Version string `json:"version"`;Hash string `json:"hash"`;Records []Record `json:"records"`}
type ZoneDrift struct{Zone string `json:"zone"`;Provider ProviderType `json:"provider"`;ExpectedHash string `json:"expected_hash"`;ObservedHash string `json:"observed_hash"`;Drifted bool `json:"drifted"`}
func SnapshotZone(ctx context.Context,provider ProviderType,zone string,records []Record)(ZoneSnapshot,error){if ctx==nil{return ZoneSnapshot{},fmt.Errorf("context is nil")};select{case<-ctx.Done():return ZoneSnapshot{},ctx.Err();default:};zone=strings.ToLower(strings.TrimSuffix(strings.TrimSpace(zone),"."));if zone==""||len(zone)>253{return ZoneSnapshot{},fmt.Errorf("zone is invalid")};if len(records)>10000{return ZoneSnapshot{},fmt.Errorf("too many zone records")};copyRecords:=append([]Record(nil),records...);for i:=range copyRecords{r:=&copyRecords[i];r.ID=strings.TrimSpace(r.ID);r.Name=strings.ToLower(strings.TrimSuffix(strings.TrimSpace(r.Name),"."));r.Type=strings.ToUpper(strings.TrimSpace(r.Type));r.Value=strings.TrimSpace(r.Value);if len(r.ID)>256||len(r.Name)>253||len(r.Type)>32||len(r.Value)>4096{return ZoneSnapshot{},fmt.Errorf("zone record field too long")}};sort.SliceStable(copyRecords,func(i,j int)bool{a,b:=copyRecords[i],copyRecords[j];ka:=fmt.Sprintf("%s|%s|%s|%d|%d",a.Name,a.Type,a.Value,a.TTL,a.Priority);kb:=fmt.Sprintf("%s|%s|%s|%d|%d",b.Name,b.Type,b.Value,b.TTL,b.Priority);return ka<kb});h:=sha256.New();for _,r:=range copyRecords{fmt.Fprintf(h,"%s|%s|%s|%d|%d\n",r.Name,r.Type,r.Value,r.TTL,r.Priority)};return ZoneSnapshot{Provider:provider,Zone:zone,Hash:hex.EncodeToString(h.Sum(nil)),Records:copyRecords},nil}
func CompareZoneSnapshot(expected,observed ZoneSnapshot)ZoneDrift{return ZoneDrift{Zone:observed.Zone,Provider:observed.Provider,ExpectedHash:expected.Hash,ObservedHash:observed.Hash,Drifted:expected.Hash!=observed.Hash}}
